#[path="../../rust/crates/genewars-runtime/src/genepod_command.rs"]mod command;
use command::*;
fn main(){let p=std::path::PathBuf::from(std::env::args().nth(1).unwrap());let input=std::fs::read(p.join("input.bin")).unwrap();let mut out=Vec::new();for row in input.chunks_exact(1879){let a=row[..67].try_into().unwrap();let b=row[67..1872].try_into().unwrap();let request=GenepodRequest{species:i16::from_le_bytes(row[1872..1874].try_into().unwrap()),building_slot:i16::from_le_bytes(row[1874..1876].try_into().unwrap()),start:row[1876]!=0};let context=GenepodCommandContext{funds_identity_player_type:row[1877],selected_panel_refresh_eligible:row[1878]!=0};let plan=plan_mule_command(&a,&b,request,context).unwrap();out.extend_from_slice(&plan.building_after);out.extend_from_slice(&plan.caller_after);out.push(u8::from(plan.panel_refresh_requested));for mutation in 0..5{let(mut a,mut b,mut q)=(a,b,request);match mutation{0=>a[6]=0,1=>a[46]=3,2=>b[0x4a1]=4,3=>q.species=5,_=>q.building_slot=-1};assert!(plan_mule_command(&a,&b,q,context).is_err());}}std::fs::write(p.join("actual.bin"),out).unwrap();}
